        margin: 24px auto 40px;
      }

      header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 18px 22px;
        margin-bottom: 20px;
        border: 1px solid var(--border);
        border-radius: var(--radius-lg);
        background: rgba(255, 255, 255, 0.82);
        backdrop-filter: blur(12px);
      }

      .brand {
        display: flex;
        align-items: center;
        gap: 12px;
        min-width: 0;
      }

      .mark {
        width: 40px;
        height: 40px;
        border-radius: 14px;
        display: grid;
        place-items: center;
        background: linear-gradient(135deg, var(--brand), #7c3aed);
        color: white;
        font-weight: 700;
      }

      .brand h1 {
        margin: 0;
        font-size: 1.05rem;
        line-height: 1.2;
      }

      .brand p {
        margin: 2px 0 0;
        color: var(--muted);
        font-size: 0.94rem;
      }

      main {
        display: grid;
        gap: 20px;
      }

      .hero {
        display: grid;
        grid-template-columns: 1.4fr 0.9fr;
        gap: 20px;
        align-items: stretch;
      }

      .panel {
        border: 1px solid var(--border);
        border-radius: var(--radius-xl);
        background: var(--surface);
        box-shadow: var(--shadow);
