        gap: 12px;
      }

      .stat {
        padding: 14px;
        border-radius: 16px;
        background: linear-gradient(180deg, #f8fbff, #eef4ff);
        border: 1px solid #dde8ff;
      }

      .stat strong {
        display: block;
        font-size: 1.15rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.92rem;
      }

      dialog {
        width: min(92vw, 520px);
        border: 1px solid var(--border);
        border-radius: 24px;
        padding: 0;
        box-shadow: var(--shadow);
        color: var(--text);
        background: var(--surface);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(4px);
      }

      .dialog-card {
        padding: 24px;
        display: grid;
        gap: 18px;
      }

      .dialog-icon {
        width: 52px;
        height: 52px;
        border-radius: 18px;
        display: grid;
        place-items: center;
        background: #fff1f2;
        color: var(--danger);
        font-size: 1.5rem;
      }

      .dialog-card h2 {
        margin: 0;
        font-size: 1.4rem;
      }

      .dialog-card p {
        margin: 0;
        color: var(--muted);
        line-height: 1.7;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        flex-wrap: wrap;
      }

      .secondary,
      .ghost,
      .destructive {
        appearance: none;
        border-radius: 14px;
        padding: 12px 16px;
        font: inherit;
        font-weight: 600;
        cursor: pointer;
        border: 1px solid transparent;
      }

      .secondary {
        background: var(--surface-alt);
        color: var(--text);
        border-color: var(--border);
      }

      .ghost {
        background: transparent;
        color: var(--muted);
        border-color: var(--border);
      }

      .destructive {
        background: linear-gradient(180deg, #ef4444, #dc2626);
